// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    RecordingToken sGlp;

    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address keeper, uint256 amount) public {
        vm.assume(keeper != address(0));
        amount = bound(amount, 1, 1e30);

        sGlp = new RecordingToken();
        RecordingToken usdc = new RecordingToken();
        MockGlpManager gm = new MockGlpManager();
        MockRewardRouter rr = new MockRewardRouter();
        MockJuniorVault jv = new MockJuniorVault();

        c.initialize(IERC20(address(sGlp)), IERC20(address(usdc)), IRewardRouterV2(address(rr)), IGlpManager(address(gm)), address(jv), address(this));
        c.grantAllowances();
        c.setKeeper(keeper);

        // seed the tracked GLP balance through the vault-only entry
        vm.prank(address(jv));
        c.depositToken(address(usdc), amount, 0);

        uint256 preBalance = c.dnGmxJuniorVaultGlpBalance();

        // two consecutive keeper batch deposits (cooldown satisfied by warping)
        vm.warp(1_000);
        vm.prank(keeper);
        c.executeBatchDeposit();
        vm.warp(1_000 + 901);
        vm.prank(keeper);
        c.executeBatchDeposit();

        // rule: total sGlp sent out across both batches must equal exactly the
        // tracked balance before the batches; the residual-tracking mutant sends 1 extra
        assertTrue(sGlp.totalSent() == preBalance);
    }
}

contract RecordingToken {
    uint256 public totalSent;
    function transfer(address, uint256 amt) external returns (bool) { totalSent += amt; return true; }
    function transferFrom(address, address, uint256) external pure returns (bool) { return true; }
    function approve(address, uint256) external pure returns (bool) { return true; }
}

contract MockGlpManager {
    function vault() external pure returns (address) { return address(1); }
}

contract MockRewardRouter {
    function mintAndStakeGlp(address, uint256 amt, uint256, uint256) external pure returns (uint256) { return amt; }
}

contract MockJuniorVault {
    function harvestFees() external {}
    function deposit(uint256, address) external pure returns (uint256) { return 0; }
    function redeem(uint256, address, address) external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
}
